jq '
def line_revenue:
  ((.qty * .unit_cents * (100 - (.discount_pct // 0))) / 100) | floor;

# Map orders to have customer key
map(. + {
  customer_key: (if .customer and .customer.id then .customer.id else "guest" end)
})
| group_by(.customer_key)
| map(
    (sort_by(.placed) | last) as $most_recent
    | (if $most_recent.customer_key == "guest" then null else $most_recent.customer.name end) as $name
    | .[0].customer_key as $cust_key
    | [.[] | select(.status == "paid")] as $paid
    | ($paid | length) as $paid_orders
    | ([ $paid[].items[] | line_revenue ] | add // 0) as $revenue_cents
    | ($paid | group_by(.placed[:7]) | map({
        key: .[0].placed[:7],
        value: ([ .[].items[] | line_revenue ] | add // 0)
      }) | sort_by(.key) | from_entries) as $by_month
    | ($paid | [ .[].items[] ] | group_by(.sku) | map({
        sku: .[0].sku,
        rev: ([ .[] | line_revenue ] | add // 0)
      }) | sort_by(-.rev, .sku) | .[:3] | map(.sku)) as $top_skus
    | {
        customer: $cust_key,
        name: $name,
        paid_orders: $paid_orders,
        revenue_cents: $revenue_cents,
        by_month: $by_month,
        top_skus: $top_skus
      }
)
' /home/eval/shop/data/orders.json

